{"script": "total_chars=$(find test_directory -type f -name '*.txt' -exec wc -c {} \; | awk '{sum += $1} END {print sum}');
total_words=$(find test_directory -type f -name '*.txt' -exec wc -w {} \; | awk '{sum += $1} END {print sum}');
total_lines=$(find test_directory -type f -name '*.txt' -exec wc -l {} \; | awk '{sum += $1} END {print sum}');
